}

pub fn fsum(values: &[f64]) -> f64 {
    let mut partials: Vec<f64> = Vec::new();
    for &x0 in values {
        let mut x = x0;
        let mut i = 0usize;
        for j in 0..partials.len() {
            let mut y = partials[j];
            if x.abs() < y.abs() {
                std::mem::swap(&mut x, &mut y);
            }
            let hi = x + y;
            let lo = y - (hi - x);
            if lo != 0.0 {
                partials[i] = lo;
                i += 1;
            }
            x = hi;
        }
        partials.truncate(i);
        partials.push(x);
    }
    let mut s = 0.0f64;
    for p in &partials {
        s += p;
    }
    s
}

pub fn py_round(x: f64, n: i32) -> f64 {
    let m = 10f64.powi(n);
    (x * m).round_ties_even() / m
}

