        }
        pool[..size].to_vec()
    }

pub fn permutation_test_shared_convergence(
    factory_verdicts: &[(String, Vec<String>)],
    universe: Option<&[String]>,
    n_perm: usize,
    seed: u64,
) -> Result<f64, PyError> {
    if factory_verdicts.is_empty() {
        return Err(verr("factory_verdicts 须为非空 dict 即厂名到命题集合映射"));
    }
    if n_perm < 1 {
        return Err(verr("n_perm 须为正整数"));
    }
    let mut sets: Vec<(String, Vec<String>)> = Vec::new();
    for (name, props) in factory_verdicts {
        let mut prop_set: Vec<String> = props.clone();
        prop_set.sort();
        prop_set.dedup();
        if props.iter().any(|p| p.is_empty()) {
            return Err(verr(format!("厂 {} 的命题 id 须为字符串", name)));
        }
        sets.push((name.clone(), prop_set));
    }
    let pool: Vec<String> = match universe {
        None => {
            let mut union: Vec<String> = sets.iter().flat_map(|(_, s)| s.iter().cloned()).collect();
            union.sort();
            union.dedup();
            union
        }
        Some(u) => {
            let mut pool: Vec<String> = u.to_vec();
            pool.sort();
            pool.dedup();
            if pool.is_empty() {
                return Err(verr("universe 为空集合"));
            }
            pool
        }
    };
    // 观测交集
    let mut observed_set: Vec<String> = sets[0].1.clone();
    for (_, s) in sets.iter().skip(1) {
        observed_set.retain(|x| s.contains(x));
    }
    let observed = observed_set.len();
    if observed == 0 || pool.is_empty() {
        return Ok(1.0);
    }
    let sizes: Vec<usize> = sets.iter().map(|(_, s)| s.len()).collect();
    for size in &sizes {
        if *size > pool.len() {
            return Err(verr("厂集合容量超过全域大小"));
        }
    }
    let mut rng = SplitMix64(seed);
    let mut hits = 0usize;
    for _ in 0..n_perm {
        let mut inter: Option<Vec<String>> = None;
        for size in &sizes {
            let drawn = rng.sample(&pool, *size);
            inter = Some(match inter {
                None => drawn,
                Some(cur) => cur.into_iter().filter(|x| drawn.contains(x)).collect(),
            });
            if inter.as_ref().map(|i| i.is_empty()).unwrap_or(false) {
                break;
            }
        }
        let inter_len = inter.as_ref().map(|i| i.len()).unwrap_or(0);
        if inter_len >= observed {
            hits += 1;
        }
    }
    Ok((hits + 1) as f64 / (n_perm + 1) as f64)
}

fn f_sf(f_value: f64, df1: f64, df2: f64) -> f64 {
    if f_value <= 0.0 {
        return 1.0;
    }
    let x = df2 / (df2 + df1 * f_value);
    reg_inc_beta(x, df2 / 2.0, df1 / 2.0)
}

fn betacf(a: f64, b: f64, x: f64) -> f64 {
    let max_iter = 200;
    let eps = 3e-12;
    let fpmin = 1e-300;
    let qab = a + b;
    let qap = a + 1.0;
    let qam = a - 1.0;
    let mut c = 1.0;
    let mut d = 1.0 - qab * x / qap;
    if d.abs() < fpmin {
        d = fpmin;
    }
    d = 1.0 / d;
    let mut h = d;
    for m in 1..=max_iter {
        let m2 = 2 * m;
        let aa = m as f64 * (b - m as f64) * x / ((qam + m2 as f64) * (a + m2 as f64));
        d = 1.0 + aa * d;
        if d.abs() < fpmin {
            d = fpmin;
        }
        c = 1.0 + aa / c;
        if c.abs() < fpmin {
            c = fpmin;
        }
        d = 1.0 / d;
        h *= d * c;
        let aa = -(a + m as f64) * (qab + m as f64) * x / ((a + m2 as f64) * (qap + m2 as f64));
        d = 1.0 + aa * d;
        if d.abs() < fpmin {
            d = fpmin;
        }
        c = 1.0 + aa / c;
        if c.abs() < fpmin {
            c = fpmin;
        }
        d = 1.0 / d;
        let delta = d * c;
        h *= delta;
        if (delta - 1.0).abs() < eps {
            break;
        }
    }
    h
}

fn reg_inc_beta(x: f64, a: f64, b: f64) -> f64 {
    if x <= 0.0 {
        return 0.0;
    }
    if x >= 1.0 {
        return 1.0;
    }
    let ln_front = lgamma(a + b) - lgamma(a) - lgamma(b)
        + a * x.ln()
        + b * (1.0 - x).ln();
    let front = ln_front.exp();
    if x < (a + 1.0) / (a + b + 2.0) {
        front * betacf(a, b, x) / a
    } else {
        1.0 - front * betacf(b, a, 1.0 - x) / b
    }
}

pub fn mixed_effects_anova(
    data: &[((String, String), Vec<f64>)],
    factor_names: (&str, &str),
) -> Result<Value, PyError> {
    if data.is_empty() {
        return Err(verr("data 须为非空 dict，factor_names 须为二元组"));
    }
    let mut cells: Vec<((String, String), Vec<f64>)> = Vec::new();
    let mut rep_counts: Vec<usize> = Vec::new();
    for (key, values) in data {
        if values.len() < 2 {
            return Err(verr(format!("单元格 {:?} 须为至少两个数值的重复观测", key)));
        }
        cells.push((key.clone(), values.clone()));
        rep_counts.push(values.len());
    }
    if rep_counts.iter().any(|r| *r != rep_counts[0]) {
        return Err(verr("平衡设计要求各单元格重复数相同"));
    }
    let r = rep_counts[0];

    let mut levels_a: Vec<String> = cells.iter().map(|((a, _), _)| a.clone()).collect();
    levels_a.sort();
    levels_a.dedup();
    let mut levels_b: Vec<String> = cells.iter().map(|((_, b), _)| b.clone()).collect();
    levels_b.sort();
    levels_b.dedup();
    let a_n = levels_a.len();
    let b_n = levels_b.len();
    if a_n < 2 || b_n < 2 {
        return Err(verr("两因素各须至少两个水平"));
    }
    for i in &levels_a {
        for j in &levels_b {
            if !cells.iter().any(|((ci, cj), _)| ci == i && cj == j) {
                return Err(verr("设计须为全因子即每水平组合都有单元格"));
            }
        }
    }

    let cell_mean = |i: &str, j: &str| -> f64 {
        let s: Vec<f64> = cells
            .iter()
            .filter(|((ci, cj), _)| ci == i && cj == j)
            .flat_map(|(_, v)| v.iter().cloned())
            .collect();
        s.iter().sum::<f64>() / s.len() as f64
    };

    let all_vals: Vec<f64> = cells.iter().flat_map(|(_, v)| v.iter().cloned()).collect();
    let grand_mean = all_vals.iter().sum::<f64>() / all_vals.len() as f64;

    let row_mean = |i: &str| -> f64 {
        levels_b.iter().map(|j| cell_mean(i, j)).sum::<f64>() / b_n as f64
    };
    let col_mean = |j: &str| -> f64 {
        levels_a.iter().map(|i| cell_mean(i, j)).sum::<f64>() / a_n as f64
    };

    let ss_a = (b_n * r) as f64
        * levels_a.iter().map(|i| (row_mean(i) - grand_mean).powi(2)).sum::<f64>();
    let ss_b = (a_n * r) as f64
        * levels_b.iter().map(|j| (col_mean(j) - grand_mean).powi(2)).sum::<f64>();
    let mut ss_ab = 0.0f64;
    for i in &levels_a {
        for j in &levels_b {
            ss_ab += (cell_mean(i, j) - row_mean(i) - col_mean(j) + grand_mean).powi(2);
        }
    }
    ss_ab *= r as f64;
    let mut ss_err = 0.0f64;
    for ((i, j), series) in &cells {
        let cm = cell_mean(i, j);
        for v in series {
            ss_err += (v - cm).powi(2);
        }
    }

    let df_a = (a_n - 1) as f64;
    let df_b = (b_n - 1) as f64;
    let df_ab = ((a_n - 1) * (b_n - 1)) as f64;
    let df_err = (a_n * b_n * (r - 1)) as f64;
    let ms_a = ss_a / df_a;
    let ms_b = ss_b / df_b;
    let ms_ab = ss_ab / df_ab;
    let ms_err = if df_err > 0.0 { ss_err / df_err } else { 0.0 };

    let block = |ss: f64, ms: f64, df_factor: f64| -> Value {
        let f_value = if ms_err == 0.0 {
            if ss == 0.0 { 0.0 } else { f64::INFINITY }
        } else {
            ms / ms_err
        };
        let mut p_value = if !f_value.is_finite() || f_value <= 0.0 {
            1.0
        } else {
            f_sf(f_value, df_factor, df_err)
        };
        if f_value.is_infinite() {
            p_value = 0.0;
        }
        json!({"ss": ss, "df": df_factor, "ms": ms, "f": f_value, "p": p_value})
    };

    Ok(json!({
        "grand_mean": grand_mean,
        "n_obs": all_vals.len(),
        "factors": {
            factor_names.0: block(ss_a, ms_a, df_a),
            factor_names.1: block(ss_b, ms_b, df_b),
            "interaction": block(ss_ab, ms_ab, df_ab),
        },
    }))
}

fn require_counts(k: i64, n: i64) -> Result<(), PyError> {
    if n < 0 {
        return Err(verr(format!("n 须非负，实际为 {}", n)));
    }
    if k < 0 || k > n {
        return Err(verr(format!("须 0 <= k <= n，实际 k = {}, n = {}", k, n)));
    }
    Ok(())
}

fn require_probability(value: f64, name: &str, open_interval: bool) -> Result<f64, PyError> {
    if open_interval {
        if !(0.0 < value && value < 1.0) {
            return Err(verr(format!("{} 须落在开区间 (0, 1)，实际为 {}", name, value)));
        }
    } else if !(0.0 <= value && value <= 1.0) {
        return Err(verr(format!("{} 须落在闭区间 [0, 1]，实际为 {}", name, value)));
    }
    Ok(value)
}

fn require_p_values(p_values: &[Value]) -> Result<Vec<f64>, PyError> {
    if p_values.is_empty() {
        return Err(verr("p_values 须非空"));
    }
    let mut out = Vec::with_capacity(p_values.len());
    for (i, item) in p_values.iter().enumerate() {
        let v = item.as_f64().ok_or_else(|| verr(format!("p_values[{}] 须为实数", i)))?;
        out.push(require_probability(v, &format!("p_values[{}]", i), false)?);
    }
    Ok(out)
}

fn log_binom(n: i64, j: i64) -> f64 {
    lgamma((n + 1) as f64) - lgamma((j + 1) as f64) - lgamma((n - j + 1) as f64)
}

fn binom_upper_tail(k: i64, n: i64, p: f64) -> f64 {
    if k == 0 {
        return 1.0;
    }
    let log_p = p.ln();
    let log_q = (1.0 - p).ln();
    let terms: Vec<f64> = (k..=n)
        .map(|j| (log_binom(n, j) + j as f64 * log_p + (n - j) as f64 * log_q).exp())
        .collect();
    fsum(&terms).min(1.0)
}

pub fn binomial_test_pvalue(k: i64, n: i64, p_h0: f64) -> Result<f64, PyError> {
    require_counts(k, n)?;
    let p = require_probability(p_h0, "p_h0", true)?;
    Ok(binom_upper_tail(k, n, p))
}

pub fn boundary_test_pvalue(k: i64, n: i64, p_h0: f64) -> Result<f64, PyError> {
    require_counts(k, n)?;
    let p = require_probability(p_h0, "p_h0", true)?;
    Ok(binom_upper_tail(k, n, p))
}

pub fn bonferroni_correction(p_values: &[Value], alpha: f64) -> Result<Vec<f64>, PyError> {
    let ps = require_p_values(p_values)?;
    require_probability(alpha, "alpha", true)?;
    let m = ps.len();
    Ok(ps.iter().map(|p| (p * m as f64).min(1.0)).collect())
}

pub fn bh_fdr(p_values: &[Value], alpha: f64) -> Result<Vec<f64>, PyError> {
    let ps = require_p_values(p_values)?;
    require_probability(alpha, "alpha", true)?;
    let m = ps.len();
    let mut order: Vec<usize> = (0..m).collect();
    order.sort_by(|a, b| ps[*a].partial_cmp(&ps[*b]).unwrap_or(std::cmp::Ordering::Equal));
    let mut adjusted = vec![0.0f64; m];
    let mut running_min = 1.0f64;
    for rank in (1..=m).rev() {
        let idx = order[rank - 1];
        let candidate = (m as f64 / rank as f64) * ps[idx];
        if candidate < running_min {
            running_min = candidate;
        }
        adjusted[idx] = running_min.min(1.0);
    }
    Ok(adjusted)
}

pub fn statistical_power(n: i64, p_h0: f64, p_h1: f64, alpha: f64) -> Result<f64, PyError> {
    if n < 1 {
        return Err(verr(format!("n 须为正整数，实际为 {}", n)));
    }
    let p0 = require_probability(p_h0, "p_h0", true)?;
    let p1 = require_probability(p_h1, "p_h1", true)?;
    let a = require_probability(alpha, "alpha", true)?;

    let log_p0 = p0.ln();
    let log_q0 = (1.0 - p0).ln();
    let terms0: Vec<f64> = (0..=n)
        .map(|j| (log_binom(n, j) + j as f64 * log_p0 + (n - j) as f64 * log_q0).exp())
        .collect();

    let mut k_star = n + 1;
    let mut suffix = 0.0f64;
    for k in (0..=n).rev() {
        suffix += terms0[k as usize];
        if suffix <= a {
            k_star = k;
        } else {
            break;
        }
    }
    if k_star == n + 1 {
        return Ok(0.0);
    }

    let log_p1 = p1.ln();
    let log_q1 = (1.0 - p1).ln();
    let terms1: Vec<f64> = (k_star..=n)
        .map(|j| (log_binom(n, j) + j as f64 * log_p1 + (n - j) as f64 * log_q1).exp())
        .collect();
    Ok(fsum(&terms1).min(1.0))
}

fn validate_vector(values: &[Value], name: &str) -> Result<Vec<f64>, PyError> {
    if values.is_empty() {
        return Err(verr(format!("{}: 输入序列为空，至少需要一个分量", name)));
    }
    let mut checked = Vec::with_capacity(values.len());
    for (index, item) in values.iter().enumerate() {
        let v = item.as_f64().ok_or_else(|| {
            verr(format!(
                "{}[{}]: 元素类型 {} 不是实数",
                name,
                index,
                py_type(item)
            ))
        })?;
        if v < 0.0 {
            return Err(verr(format!("{}[{}]: 元素为负数 {}", name, index, v)));
        }
        checked.push(v);
    }
    Ok(checked)
}

fn py_type(v: &Value) -> &'static str {
    match v {
        Value::String(_) => "str",
        Value::Bool(_) => "bool",
        Value::Number(_) => "float",
        Value::Null => "NoneType",
        _ => "object",
    }
}

fn normalize(vector: &[f64], name: &str) -> Result<Vec<f64>, PyError> {
    let total = fsum(vector);
    if total <= 0.0 {
        return Err(verr(format!("{}: 全零向量无法归一化为概率分布", name)));
    }
    Ok(vector.iter().map(|x| x / total).collect())
}

fn validated_pair(p: &[Value], q: &[Value]) -> Result<(Vec<f64>, Vec<f64>), PyError> {
    let vp = validate_vector(p, "p")?;
    let vq = validate_vector(q, "q")?;
    if vp.len() != vq.len() {
        return Err(verr(format!(
            "p 与 q 长度不等：len(p)={} 对 len(q)={}",
            vp.len(),
            vq.len()
        )));
    }
    Ok((vp, vq))
}

pub fn hellinger_distance(p: &[Value], q: &[Value]) -> Result<f64, PyError> {
    let (vp, vq) = validated_pair(p, q)?;
    let pn = normalize(&vp, "p")?;
    let qn = normalize(&vq, "q")?;
    let terms: Vec<f64> = pn
        .iter()
        .zip(qn.iter())
        .map(|(a, b)| (a.sqrt() - b.sqrt()).powi(2))
        .collect();
    Ok(fsum(&terms).sqrt() / 2.0f64.sqrt())
}

pub fn tv_distance(p: &[Value], q: &[Value]) -> Result<f64, PyError> {
    let (vp, vq) = validated_pair(p, q)?;
    let pn = normalize(&vp, "p")?;
    let qn = normalize(&vq, "q")?;
    let terms: Vec<f64> = pn.iter().zip(qn.iter()).map(|(a, b)| (a - b).abs()).collect();
    Ok(0.5 * fsum(&terms))
}

pub fn js_divergence(p: &[Value], q: &[Value]) -> Result<f64, PyError> {
    let (vp, vq) = validated_pair(p, q)?;
    let pn = normalize(&vp, "p")?;
    let qn = normalize(&vq, "q")?;
    let mut total = 0.0f64;
    for (a, b) in pn.iter().zip(qn.iter()) {
        let m = 0.5 * (a + b);
        if *a > 0.0 {
            total += 0.5 * a * (a / m).ln();
        }
        if *b > 0.0 {
            total += 0.5 * b * (b / m).ln();
        }
    }
    Ok(total)
}

pub fn generalized_jaccard(p: &[Value], q: &[Value]) -> Result<f64, PyError> {
    let (va, vb) = validated_pair(p, q)?;
    let denominator = fsum(&va.iter().zip(vb.iter()).map(|(x, y)| x.max(*y)).collect::<Vec<_>>());
    if denominator == 0.0 {
        return Err(verr("p 与 q 全零，Σmax = 0，广义 Jaccard 无定义"));
    }
    let numerator = fsum(&va.iter().zip(vb.iter()).map(|(x, y)| x.min(*y)).collect::<Vec<_>>());
    Ok(numerator / denominator)
}

