            }
            "--miss-log" => {
                let Some(v) = argv.get(i + 1) else { fail("参数缺值", 2); };
                miss_log = Some(v.clone());
                i += 2;
            }
            other => fail(&format!("未知参数 {other}"), 2),
        }
    }

    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    let Some(root) = derive_root(&cwd) else {
        fail("工作区根不可定位即上溯无 sih-engine 与 sih-tools 并存层", 2);
    };

    let args = RecallArgs {
        root,
        topics,
        words,
        events,
        since,
        until,
        archives,
        at: at.unwrap_or_default(),
        miss_log: miss_log.map(PathBuf::from),
    };

    match recall(&args) {
        Ok(rows) => {
            if let Some(path) = args_out(&out) {
                match write_output_envelope(&path, &rows, &args.topics) {
                    Ok(()) => std::process::exit(0),
                    Err(e) => fail(&format!("{e:?}"), exit_code(&e)),
                }
            }
            print!("{}", rows_to_ndjson(&rows));
            std::process::exit(0);
        }
        Err(e) => fail(&format!("{e:?}"), exit_code(&e)),
    }
}

fn args_out(out: &Option<String>) -> Option<PathBuf> {
    out.as_ref().map(PathBuf::from)
}

fn gate_actor() -> Actor {
    Actor {
        actor_id: "scribe".to_string(),
        actor_type: ActorType::System,
        invoked_via: "cli".to_string(),
    }
}

enum ConfirmQuery {
    Hash(String),
    EventId(String),
}

fn read_text(path: &str) -> Option<String> {
    std::fs::read_to_string(path).ok()
}

fn emit(value: serde_json::Value, code: i32) -> ! {
    println!("{}", serde_json::to_string_pretty(&value).unwrap());
    exit(code)
}

fn load_store(trail: &str) -> Vec<Event> {
    let path = PathBuf::from(trail);
    if !path.exists() {
        return Vec::new();
    }
    match load_events(path.as_path()) {
        Ok(events) => events,
        Err(e) => emit(json!({"error": format!("trail 不可读 {e:?}")}), 2),
    }
}

fn lockgate_guard(opts: &std::collections::HashMap<String, String>, trail: &str) {
    let Some(locks) = opts.get("locks") else { return };
    match check_locks(
        Path::new(locks),
        Path::new(trail),
        opts.get("session").map(|s| s.as_str()),
    ) {
        Ok(()) => {}
        Err(LockGateError::Held { holders }) => {
            emit(json!({"error": "链路径在他会话锁下", "holders": holders}), 1)
        }
        Err(LockGateError::Unreadable(e)) => {
            emit(json!({"error": format!("锁台账不可读 {e}")}), 2)
        }
    }
}

fn worktree_trail_guard(opts: &std::collections::HashMap<String, String>, trail: &str) {
    let path = PathBuf::from(trail);
    let contains_worktree = path
        .components()
        .any(|c| c.as_os_str() == "worktrees");
    if !contains_worktree {
        return;
    }
    if opts.get("allow-worktree-trail").map(|s| s == "1" || s == "true").unwrap_or(false) {
        return;
    }
    emit(json!({"error": "工地链副本禁追加即认证先落主链"}), 2);
}

fn session_guard(opts: &std::collections::HashMap<String, String>) -> Option<String> {
    let session = opts.get("session").map(|s| s.as_str());
    let reason = opts.get("no-session-reason").cloned();
    if session.is_none() && reason.is_some() {
        return reason; // 主会处置位：无会话号但显式给事由即放行，由写分支落链。
    }
    if session.is_none() {
        emit(
            json!({"error": "会话不在册即拒 SessionNotActive：缺 --session，主会处置位 --no-session-reason <事由> 默认关"}),
            1,
        );
    }
    let Some(sessions) = opts.get("sessions") else {
        emit(json!({"error": "会话在册验需 --sessions <会话台账路径>"}), 2);
    };
    match check_session(Path::new(sessions), session, None) {
        Ok(_) => None,
        Err(SessionGateError::NotActive { session_id }) => {
            emit(
                json!({"error": "会话不在册即拒 SessionNotActive", "session_id": session_id}),
                1,
            )
        }
        Err(SessionGateError::Unreadable(e)) => {
            emit(json!({"error": format!("会话台账不可读 {e}")}), 2)
        }
    }
}

fn resolve_envelope(
    sessions: Option<&str>,
    session: Option<&str>,
) -> Result<Option<(String, Option<String>)>, String> {
    let Some(sid) = session else { return Ok(None) };
    let Some(sp) = sessions else { return Ok(None) };
    let text = std::fs::read_to_string(sp).map_err(|e| format!("会话台账不可读 {e}"))?;
    let mut identity: Option<String> = None;
    let mut active = false;
    for line in text.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let row: serde_json::Value = serde_json::from_str(line).map_err(|_| "会话台账行非法".to_string())?;
        if row.get("session_id").and_then(|v| v.as_str()) != Some(sid) {
            continue;
        }
        match row.get("event").and_then(|v| v.as_str()) {
            Some("issued") => {
                active = true;
                identity = row
                    .get("identity")
                    .and_then(|v| v.get("identity_hash"))
                    .and_then(|v| v.as_str())
                    .map(|s| s.to_string());
            }
            Some("revoked") => active = false,
            _ => {}
        }
    }
    if active {
        Ok(Some((sid.to_string(), identity)))
    } else {
        Ok(None)
    }
}

fn bind_envelope(opts: &std::collections::HashMap<String, String>, input: &mut EventInput) {
    let sessions = opts.get("sessions").map(|s| s.as_str());
    let session = opts.get("session").map(|s| s.as_str());
    match resolve_envelope(sessions, session) {
        Ok(Some((sid, id_hash))) => {
            input.session_id = Some(sid);
            input.identity_hash = id_hash;
        }
        Ok(None) => {}
        Err(e) => emit(json!({"error": e}), 2),
    }
}

fn print_usage() {
    println!("{}", USAGE);
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let cmd = args.get(1).map(|s| s.as_str()).unwrap_or("");
    if cmd == "--help" || cmd == "-h" || cmd == "help" || cmd.is_empty() {
        print_usage();
        if cmd.is_empty() {
            exit(2);
        }
        return;
    }
    let mut opts = std::collections::HashMap::new();
    let mut i = 2;
    while i + 1 < args.len() + 1 && i < args.len() {
        if args[i].starts_with("--") && i + 1 < args.len() {
            opts.insert(args[i].trim_start_matches('-').to_string(), args[i + 1].clone());
            i += 2;
        } else {
            i += 1;
        }
    }
    let opt = |k: &str| opts.get(k).cloned();

    match cmd {
        "verify" => {
            let Some(trail) = opt("trail") else { emit(json!({"error": "verify 缺 --trail，用法：scribe verify --trail <链文件>"}), 2) };
            let Some(text) = read_text(&trail) else {
                emit(json!({"error": "trail 不存在"}), 2)
            };
            let _ = text;
            let events = load_store(&trail);
            match verify(&events, VerifyRange::Full) {
                Ok(ok) => emit(
                    json!({
                        "status": "valid",
                        "events": ok.event_count,
                        "first_hash": ok.first_hash,
                        "last_hash": ok.last_hash,
                    }),
                    0,
                ),
                Err(e) => emit(json!({"status": "broken", "error": format!("{e:?}")}), 1),
            }
        }
        "confirm" => {
            // chainstamp-solo 写即回执廉价查疑通道：单笔在档确认，零全文校验
            let Some(trail) = opt("trail") else { emit(json!({"error": "confirm 缺 --trail，用法：scribe confirm --trail <链文件> --hash <前八位及以上> | --event-id <事件ID>"}), 2) };
            let hashq = opt("hash");
            let idq = opt("event-id");
            if !std::path::Path::new(&trail).exists() {
                emit(json!({"error": "trail 不存在"}), 2);
            }
            let query: ConfirmQuery = match (hashq, idq) {
                (Some(h), None) => {
                    if h.len() < 8 {
                        emit(json!({"error": "confirm --hash 前缀须八位起", "given_len": h.len()}), 2);
                    }
                    ConfirmQuery::Hash(h)
                }
                (None, Some(i)) => ConfirmQuery::EventId(i),
                _ => emit(json!({"error": "confirm 须 --hash 与 --event-id 二择一，用法：scribe confirm --trail <链文件> --hash <前八位及以上> | --event-id <事件ID>"}), 2),
            };
            let events = load_store(&trail);
            let hit = events.iter().enumerate().find(|(_, e)| match &query {
                ConfirmQuery::Hash(h) => e.event_hash.starts_with(h.as_str()),
                ConfirmQuery::EventId(i) => e.event_id == *i,
            });
            match hit {
                Some((idx, e)) => emit(
                    json!({
                        "found": true,
                        "index": idx,
                        "event_type": e.event_type,
                        "event_hash": e.event_hash,
                        "event_id": e.event_id,
                    }),
                    0,
                ),
                None => {
                    let queried = match &query {
                        ConfirmQuery::Hash(h) => json!(format!("hash:{}…", &h[..8])),
                        ConfirmQuery::EventId(i) => json!(i),
                    };
                    emit(json!({"found": false, "queried": queried}), 1)
                }
            }
        }
        "query" => {
            let Some(trail) = opt("trail") else { emit(json!({"error": "query 缺少 --trail，用法：scribe query --trail <链文件>"}), 2) };
            let events = load_store(&trail);
            if events.is_empty() && !PathBuf::from(&trail).exists() {
                emit(json!({"error": "trail 不存在"}), 2);
            }
            let filter = EventFilter {
                event_type: opt("event-type"),
                doc_id: opt("doc-id"),
                ..Default::default()
            };
            let list = query(&events, Some(filter), None);
            if list.events.is_empty() {
                emit(json!({"matches": 0}), 1);
            }
            emit(json!({"matches": list.events.len(), "events": list.events}), 0);
        }
        "append" => {
            let (Some(report), Some(exit_code), Some(trail)) =
                (opt("report"), opt("exit-code"), opt("trail"))
            else {
                emit(json!({"error": "append 缺少必填参数，需 --report <报告文件> --exit-code <退出码> --trail <链文件>"}), 2)
            };
            lockgate_guard(&opts, &trail);
            worktree_trail_guard(&opts, &trail);
            let Ok(exit_code) = exit_code.parse::<i32>() else {
                emit(json!({"error": "退出码非数"}), 2)
            };
            session_guard(&opts);
            let Some(text) = read_text(&report) else { emit(json!({"error": "报告不存在"}), 2) };
            let mut store = load_store(&trail);
            // 追加原子化重试（basefix-solo 批 F-2）：并发下他进程先行落链使
            // 本进程预取时间戳不越新链尾即拒 TimestampNotMonotonic，取新鲜
            // 时间戳有界重试三次，事件内容仍由报告件确定性派生零伪造。
            let mut attempt = 0u8;
            loop {
                let mut input = match certification_event(
                    PathBuf::from(&report).as_path(),
                    &text,
                    exit_code,
                    gate_actor(),
                    Utc::now(),
                ) {
                    Ok(i) => i,
                    Err(e) => emit(json!({"error": format!("报告不识别 {e:?}")}), 2),
                };
                bind_envelope(&opts, &mut input);
                match append(input, &mut store, Some(&PathBuf::from(&trail))) {
                    Ok(ok) => emit(
                        json!({"status": "appended", "event_id": ok.event_id, "event_hash": ok.event_hash}),
                        0,
                    ),
                    Err(AppendError::TimestampNotMonotonic { .. }) if attempt < 3 => {
                        attempt += 1;
                        continue;
                    }
                    Err(e) => emit(json!({"error": format!("写入拒 {e:?}")}), 1),
                }
            }
        }
        "intent" => {
            let (Some(record), Some(trail)) = (opt("record"), opt("trail")) else {
                emit(json!({"error": "intent 缺少必填参数，需 --record <意图记录> --trail <链文件>；ask3 形另需 --validation <验证件>（plain 形豁免，DES-016）"}), 2)
            };
            lockgate_guard(&opts, &trail);
            worktree_trail_guard(&opts, &trail);
            session_guard(&opts);
            let Some(rtext) = read_text(&record) else {
                emit(json!({"error": "记录件缺失"}), 2)
            };
            let validation_pair = opt("validation").map(|v| {
                let vtext = read_text(&v);
                match vtext {
                    Some(t) => (PathBuf::from(&v), t),
                    None => emit(json!({"error": "验证件缺失"}), 2),
                }
            });
            let scope = match load_parking_scope(Path::new(&trail)) {
                Ok(s) => s,
                Err(e) => emit(json!({"error": format!("重放面不可读 {e:?}")}), 2),
            };
            let allow_reintent = opts.get("allow-reintent").map(|s| s == "1" || s == "true").unwrap_or(false);
            match check_intent_reused(&scope, &record, allow_reintent) {
                Ok(()) => {}
                Err(sih_engine::event_stream::intent::IntentError::IntentRecordUsed) => {
                    emit(json!({"error": "意图记录已用即拒 IntentRecordUsedRejected，主会处置位 --allow-reintent 默认关"}), 1)
                }
                Err(e) => emit(json!({"error": format!("重意图拒异常 {e:?}")}), 2),
            }
            let mut input = match intent_event(
                PathBuf::from(&record).as_path(),
                &rtext,
                validation_pair.as_ref().map(|(p, t)| (p.as_path(), t.as_str())),
                gate_actor(),
                Utc::now(),
            ) {
                Ok(i) => i,
                Err(e) => emit(json!({"error": format!("意图拒 {e:?}")}), 1),
            };
            bind_envelope(&opts, &mut input);
            let mut store = load_store(&trail);
            match append(input, &mut store, Some(&PathBuf::from(&trail))) {
                Ok(ok) => emit(
                    json!({"status": "appended", "event_id": ok.event_id, "event_hash": ok.event_hash}),
                    0,
                ),
                Err(e) => emit(json!({"error": format!("写入拒 {e:?}")}), 1),
            }
        }
        "park" => {
            let (Some(record), Some(trail)) = (opt("record"), opt("trail")) else {
                emit(json!({"error": "park 缺少必填参数，需 --record <停泊记录 JSON> --trail <链文件>"}), 2)
            };
            lockgate_guard(&opts, &trail);
            worktree_trail_guard(&opts, &trail);
            let Some(text) = read_text(&record) else { emit(json!({"error": "记录不存在"}), 2) };
            let store = load_store(&trail);
            let scope = match load_parking_scope(Path::new(&trail)) {
                Ok(s) => s,
                Err(e) => emit(json!({"error": format!("重放面不可读 {e:?}")}), 2),
            };
            let mut input = match park_event(&text, &scope, gate_actor(), Utc::now()) {
                Ok(i) => i,
                Err(e) => emit(json!({"error": format!("停泊拒 {e:?}")}), 1),
            };
            bind_envelope(&opts, &mut input);
            let mut store = store;
            match append(input, &mut store, Some(&PathBuf::from(&trail))) {
                Ok(ok) => emit(
                    json!({"status": "appended", "event_id": ok.event_id, "event_hash": ok.event_hash}),
                    0,
                ),
                Err(e) => emit(json!({"error": format!("写入拒 {e:?}")}), 1),
            }
        }
        "record" => {
            let (Some(reading), Some(trail)) = (opt("reading"), opt("trail")) else {
                emit(json!({"error": "record 缺少必填参数，需 --reading <读数件> --trail <链文件>"}), 2)
            };
            lockgate_guard(&opts, &trail);
            worktree_trail_guard(&opts, &trail);
            let Some(text) = read_text(&reading) else { emit(json!({"error": "读数件不存在"}), 2) };
            let mut input = match reading_event(&text, gate_actor()) {
                Ok(i) => i,
                Err(e) => emit(json!({"error": format!("读数守卫拒 {e}")}), 1),
            };
            bind_envelope(&opts, &mut input);
            let doc_id = input.doc_id.clone();
            let mut store = load_store(&trail);
            match append(input, &mut store, Some(&PathBuf::from(&trail))) {
                Ok(ok) => emit(
                    json!({
                        "status": "appended",
                        "event_id": ok.event_id,
                        "event_hash": ok.event_hash,
                        "doc_id": doc_id,
                    }),
                    0,
                ),
                Err(e) => emit(json!({"error": format!("写入拒 {e:?}")}), 1),
            }
        }
        "crosscheck" => {
            let (Some(report), Some(material), Some(trail)) =
                (opt("report"), opt("material"), opt("trail"))
            else {
                emit(json!({"error": "record 缺少必填参数，运行 scribe --help 查看用法"}), 2)
            };
            lockgate_guard(&opts, &trail);
            let Some(text) = read_text(&report) else { emit(json!({"error": "报告不存在"}), 2) };
            let Some(mat_text) = read_text(&material) else {
                emit(json!({"error": format!("所指材料不存在 {material}")}), 2)
            };
            let mut input = match crosscheck_event(&text, &mat_text, gate_actor()) {
                Ok(i) => i,
                Err(e) => emit(json!({"error": format!("跨方核毕守卫拒 {e}")}), 1),
            };
            bind_envelope(&opts, &mut input);
            let doc_id = input.doc_id.clone();
            let mut store = load_store(&trail);
            match append(input, &mut store, Some(&PathBuf::from(&trail))) {
                Ok(ok) => emit(
                    json!({
                        "status": "appended",
                        "event_id": ok.event_id,
                        "event_hash": ok.event_hash,
                        "doc_id": doc_id,
                    }),
                    0,
                ),
                Err(e) => emit(json!({"error": format!("写入拒 {e:?}")}), 1),
            }
        }
        "vectors" => {
            let Some(out) = opt("write") else { emit(json!({"error": "缺 --write"}), 2) };
            let vectors = golden_vectors();
            let text = serde_json::to_string_pretty(&vectors).unwrap();
            std::fs::write(&out, text).expect("向量集写入");
            emit(json!({"status": "written", "count": vectors.as_array().map(|a| a.len()).unwrap_or(0)}), 0);
        }
        "direct" => {
            // 直改笔形（idenlane-envelope-solo 批）：无租约轻量链笔，agent
            // 笔强制挂 --identity-report，human 笔接口位（human seat 件在
            // 批 B，批 A 留接口位校验形 + 测试跳过形）。
            let (Some(record), Some(trail)) = (opt("record"), opt("trail")) else {
                emit(json!({"error": "direct 缺少必填参数，需 --record <直改链笔 JSON> --trail <链文件>"}), 2)
            };
            lockgate_guard(&opts, &trail);
            worktree_trail_guard(&opts, &trail);
            session_guard(&opts);
            let Some(text) = read_text(&record) else { emit(json!({"error": "记录不存在"}), 2) };
            let record_value: serde_json::Value = match serde_json::from_str(&text) {
                Ok(v) => v,
                Err(e) => emit(json!({"error": format!("记录非法 JSON {e}")}), 2),
            };
            let pen_form = record_value.get("pen_form").and_then(|v| v.as_str()).unwrap_or("");
            let pen_kind = record_value.get("pen_kind").and_then(|v| v.as_str()).unwrap_or("");
            if pen_form != "direct" {
                emit(json!({"error": "pen_form 必为 direct"}), 1);
            }
            let actor_id = record_value.get("actor_id").and_then(|v| v.as_str()).unwrap_or("unknown");
            let files = record_value.get("files").and_then(|v| v.as_array()).cloned().unwrap_or_default();
            let subject = record_value.get("subject").and_then(|v| v.as_str()).unwrap_or("");
            let timestamp_str = record_value.get("timestamp").and_then(|v| v.as_str()).unwrap_or("");
            let timestamp: chrono::DateTime<chrono::Utc> = if timestamp_str.is_empty() {
                chrono::Utc::now()
            } else {
                match chrono::DateTime::parse_from_rfc3339(timestamp_str) {
                    Ok(t) => t.with_timezone(&chrono::Utc),
                    Err(_) => emit(json!({"error": "timestamp 非 ISO8601"}), 1),
                }
            };
            // 笔形分类判定语义一裁（idenlane-envelope-solo 批 F-5）：
            // agent 笔强制挂 --identity-report 拒未挂；human 笔接口位留
            // 批 B（human seat 件）；其他笔形拒。
            let id_report_path = opt("identity-report");
            let human_seat_path = opt("human-seat");
            let session_opt = opts.get("session").map(|s| s.as_str());
            let mut actor = Actor {
                actor_id: actor_id.to_string(),
                actor_type: ActorType::Human,
                invoked_via: "direct-pen".to_string(),
            };
            let mut identity_hash: Option<String> = None;
            let mut session_id_to_bind: Option<String> = None;
            match pen_kind {
                "agent" => {
                    let Some(irp) = id_report_path else {
                        emit(json!({"error": "agent 笔强制 --identity-report 正身报告，拒未挂"}), 1);
                    };
                    let Some(ir_text) = read_text(&irp) else {
                        emit(json!({"error": format!("正身报告不可读 {irp}")}), 2);
                    };
                    let ir: serde_json::Value = match serde_json::from_str(&ir_text) {
                        Ok(v) => v,
                        Err(e) => emit(json!({"error": format!("正身报告非法 {e}")}), 2),
                    };
                    identity_hash = ir
                        .get("identity")
                        .and_then(|v| v.get("hash"))
                        .and_then(|v| v.as_str())
                        .map(|s| s.to_string());
                    if identity_hash.is_none() {
                        emit(json!({"error": "正身报告缺 identity.hash"}), 1);
                    }
                    actor.actor_type = ActorType::Agent;
                    if let Some(sid) = session_opt {
                        session_id_to_bind = Some(sid.to_string());
                    }
                }
                "human" => {
                    // human 笔接口位：批 B 实装 human seat 件前，--human-seat
                    // 必挂且为合法 JSON 对象含 seat=="human"，否则拒。
                    // 测试跳过形即 --allow-human-stub 旗标供 TDD 跳过此验。
                    let allow_stub = opts.get("allow-human-stub").map(|s| s == "1" || s == "true").unwrap_or(false);
                    if !allow_stub {
                        let Some(hsp) = human_seat_path else {
                            emit(json!({"error": "human 笔强制 --human-seat 验真件（批 B 承载），或 --allow-human-stub 1 跳过（测试形）"}), 1);
                        };
                        let Some(hs_text) = read_text(&hsp) else {
                            emit(json!({"error": format!("人席位验真件不可读 {hsp}")}), 2);
                        };
                        let hs: serde_json::Value = match serde_json::from_str(&hs_text) {
                            Ok(v) => v,
                            Err(e) => emit(json!({"error": format!("人席位验真件非法 {e}")}), 2),
                        };
                        if hs.get("seat").and_then(|v| v.as_str()) != Some("human") {
                            emit(json!({"error": "人席位验真件 seat 字段必为 human"}), 1);
                        }
                        if hs.get("name").and_then(|v| v.as_str()).map_or(true, |s| s.is_empty()) {
                            emit(json!({"error": "人席位验真件缺 name 字段"}), 1);
                        }
                        if hs.get("attest_at").and_then(|v| v.as_str()).map_or(true, |s| s.is_empty()) {
                            emit(json!({"error": "人席位验真件缺 attest_at 字段"}), 1);
                        }
                    }
                    actor.actor_type = ActorType::Human;
                }
                _ => emit(json!({"error": "pen_kind 必为 agent 或 human"}), 1),
            }
            // 直改链笔事件构造：event_type = direct_edit_completed，
            // event_class = record_only，details 载笔体（pen_form、pen_kind、
            // actor_id、files、subject、timestamp）；envelope 字段即
            // session_id + identity_hash 由 bind_envelope 与本批手动注入。
            let event_id = uuid::Uuid::new_v4().to_string();
            let doc_id = format!("direct-{pen_kind}-{}", &event_id[..8]);
            let details = json!({
                "pen_form": pen_form,
                "pen_kind": pen_kind,
                "actor_id": actor_id,
                "files": files,
                "subject": subject,
                "timestamp": timestamp.to_rfc3339(),
            });
            let mut input = EventInput {
                event_id: event_id.clone(),
                event_type: "direct_edit_completed".to_string(),
                timestamp,
                actor,
                details: Some(details),
                doc_id: doc_id.clone(),
                prev_hash: None,
                event_class: Some("record_only".to_string()),
                verification_result: None,
                session_id: None,
                identity_hash: None,
            };
            // 直改笔形信封：session_id 与 identity_hash 注入
            if let Some(sid) = session_id_to_bind {
                input.session_id = Some(sid);
            }
            input.identity_hash = identity_hash;
            // human 笔无 identity_hash 走 None（受保护：None 跳过 hash 入）
            let mut store = load_store(&trail);
            match append(input, &mut store, Some(&PathBuf::from(&trail))) {
                Ok(ok) => emit(
                    json!({
                        "status": "appended",
                        "event_id": ok.event_id,
                        "event_hash": ok.event_hash,
                        "doc_id": doc_id,
                    }),
                    0,
                ),
                Err(e) => emit(json!({"error": format!("写入拒 {e:?}")}), 1),
            }
        }
        _ => emit(
            json!({"error": "用法 scribe <append|verify|query|intent|park|record|crosscheck|direct|vectors> --trail <路径>"}),
            2,
        ),
    }
}

fn golden_vectors() -> serde_json::Value {
    use chrono::{DateTime, Utc};
    use sih_engine::event_stream::event::{Actor, ActorType, Event};
    let base_actor = || Actor {
        actor_id: "scribe".to_string(),
        actor_type: ActorType::System,
        invoked_via: "cli".to_string(),
    };
    let ts = |s: &str| DateTime::parse_from_rfc3339(s).unwrap().with_timezone(&Utc);
    let mut out = Vec::new();
    let mut build = |class: &str, event: Event| {
        let expected = compute_event_hash(&event);
        out.push(json!({
            "class": class,
            "name": event.doc_id.clone(),
            "event": serde_json::to_value(&event).unwrap(),
            "expected_hash": expected,
        }));
    };
    let mk = |event_id: &str, event_type: &str, timestamp: chrono::DateTime<Utc>,
              details: Option<serde_json::Value>, doc_id: &str,
              event_class: Option<String>, verification_result: Option<serde_json::Value>| {
        let mut e = Event {
            event_id: event_id.to_string(),
            event_type: event_type.to_string(),
            timestamp,
            actor: base_actor(),
            details,
            doc_id: doc_id.to_string(),
            prev_hash: GENESIS_PREV_HASH.to_string(),
            event_hash: String::new(),
            event_class,
            verification_result,
            session_id: None,
            identity_hash: None,
        };
        e.event_hash = compute_event_hash(&e);
        e
    };
    build("genesis", mk("00000000-0000-4000-8000-000000000001", "session_open",
        ts("2026-08-27T00:00:00Z"), Some(json!({"note": "genesis"})), "vec-genesis", None, None));
    build("details_null", mk("00000000-0000-4000-8000-000000000002", "session_close",
        ts("2026-08-27T00:00:01Z"), None, "vec-details-null", None, None));
    build("optional_absent", mk("00000000-0000-4000-8000-000000000003", "task_completion",
        ts("2026-08-27T00:00:02.500Z"), Some(json!({"task": "t"})), "vec-optional", None, None));
    build("non_ascii", mk("00000000-0000-4000-8000-000000000004", "certification_completed",
        ts("2026-08-27T00:00:03Z"), Some(json!({"词": "书简融回", "路径": "副本/核阅"})),
        "vec-非ASCII", Some("record_only".to_string()), None));
    build("timestamp_edge", mk("00000000-0000-4000-8000-000000000005", "parking_entered",
        ts("2026-08-27T23:59:59.999999+00:00"), Some(json!({"entry_id": "vec-5"})),
        "vec-ts-edge", Some("record_only".to_string()),
        Some(json!({"exit_code": 0, "findings": 0, "total": 0}))));
    json!(out)
}

struct CliOutput {
    error: String,
}

fn emit(value: serde_json::Value, code: i32) -> ! {
    println!("{}", serde_json::to_string_pretty(&value).unwrap());
    exit(code)
}

fn read_text(path: &str) -> Option<String> {
    std::fs::read_to_string(path).ok()
}

fn target_in_domain(dom: &sih_engine::scrutinator::rule::DomainSpec, path: &str) -> bool {
    let abs = std::fs::canonicalize(path)
        .ok()
        .and_then(|p| p.to_str().map(String::from))
        .unwrap_or_else(|| path.to_string());
    if sih_engine::scrutinator::rule::domain_match(dom, &abs)
        || sih_engine::scrutinator::rule::domain_match(dom, path)
    {
        return true;
    }
    match sih_engine::scrutinator::rule::discover_workspace_root(&abs) {
        Some(root) => sih_engine::scrutinator::rule::domain_match_rooted(dom, &root, &abs),
        None => false,
    }
}

struct Parsed {
    /// 每个 --pack 的值，按出现顺序
    pack_names: Vec<String>,
    /// 每个 --target 的值（旗标别名），按出现顺序
    flag_targets: Vec<String>,
    /// 位置参数目标，按出现顺序（--pack 旗标值之后、非 -- 开头的参数）
    positional_targets: Vec<String>,
}

fn parse_args(args: &[String]) -> Parsed {
    let mut pack_names: Vec<String> = Vec::new();
    let mut flag_targets: Vec<String> = Vec::new();
    let mut positional_targets: Vec<String> = Vec::new();
    let mut i = 0;
    while i < args.len() {
        if args[i] == "--pack" {
            if i + 1 < args.len() {
                pack_names.push(args[i + 1].clone());
                i += 2;
            } else {
                i += 1;
            }
        } else if args[i] == "--target" {
            if i + 1 < args.len() {
                flag_targets.push(args[i + 1].clone());
                i += 2;
            } else {
                i += 1;
            }
        } else if args[i].starts_with("--") {
            // 未知旗标：跳过旗标与其值（若 value 不以 -- 开头则认为是旗标值）
            if i + 1 < args.len() && !args[i + 1].starts_with("--") {
                i += 2;
            } else {
                i += 1;
            }
        } else {
            // 位置参数
            positional_targets.push(args[i].clone());
            i += 1;
        }
    }
    Parsed {
        pack_names,
        flag_targets,
        positional_targets,
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    // 跳过 argv[0]（binary 名）
    let parsed = parse_args(&args[1..]);

    // 装载：--pack 可重复，未传走默认三包全量
    let pack_names: Vec<String> = if !parsed.pack_names.is_empty() {
        parsed.pack_names.clone()
    } else {
        // 未传 --pack = 走默认三包（决定空载形与否：传 --pack 但取空值才是空载）
        PACK_NAMES.iter().map(|s| s.to_string()).collect()
    };

    // 缺包检查：未知名包产退出码 2
    let pack_refs: Vec<&str> = pack_names.iter().map(|s| s.as_str()).collect();
    let packs_data = match load_packs(&pack_refs) {
        Ok(v) => v,
        Err(e) => {
            emit(
                serde_json::to_value(&CliOutput { error: e }).unwrap(),
                2,
            );
        }
    };

    // 目标收集：旗标 target + 位置参数 target 按出现顺序取并集
    // 这里为了语义最简：合并去重但保持首次出现顺序
    let mut target_paths: Vec<String> = Vec::new();
    let mut seen = std::collections::HashSet::new();
    for t in &parsed.flag_targets {
        if seen.insert(t.clone()) {
            target_paths.push(t.clone());
        }
    }
    for t in &parsed.positional_targets {
        if seen.insert(t.clone()) {
            target_paths.push(t.clone());
        }
    }

    // 空载形：未传任何 target（包括位置参数），产 packs=[] 报告、findings=[]、退出码 0
    if target_paths.is_empty() {
        let report = render_report(&packs_data, &[], &[]);
        emit(serde_json::to_value(&report).unwrap(), 0);
    }

    // 域判定：每个 target 必须命中至少一个包域；都未命中则产 domain_mismatch 并退出码 2
    let mut all_in_domain = true;
    let mut domain_mismatches: Vec<String> = Vec::new();
    for path in &target_paths {
        let in_any = packs_data
            .iter()
            .any(|(_, dom, _)| target_in_domain(dom, path));
        if !in_any {
            all_in_domain = false;
            domain_mismatches.push(path.clone());
        }
    }
    if !all_in_domain {
        let mut packs_map = serde_json::Map::new();
        for (name, dom, _) in &packs_data {
            packs_map.insert(
                name.clone(),
                serde_json::json!({"include": dom.include, "exclude": dom.exclude}),
            );
        }
        let out = serde_json::json!({
            "error": "目标不在任何已加载规则包声明的治理域内",
            "unmatched_targets": domain_mismatches,
            "packs": serde_json::Value::Object(packs_map),
        });
        emit(out, 2);
    }

    // 加载目标文本/JSON
    let mut targets: Vec<(String, Option<String>)> = Vec::new();
    for path in &target_paths {
        let text = read_text(path);
        // 目标 path 用绝对路径，与工具件 Python `str(pathlib.Path(target).resolve())` 对表
        let abs_path = std::fs::canonicalize(path)
            .ok()
            .and_then(|p| p.to_str().map(String::from))
            .unwrap_or_else(|| path.clone());
        targets.push((abs_path, text));
    }

    // 跑规则：每个 pack 只跑在它域内的 target
    let mut findings = Vec::new();
    for (pack_name, dom, rules) in &packs_data {
        for (path, text_opt) in &targets {
            if let Some(text) = text_opt {
                // 域内判定：target 在 pack 域内才跑（scrutpath-solo 起含根锚定工地形）
                let in_domain = target_in_domain(dom, path);
                if !in_domain {
                    continue;
                }
                // finding 的 path 字段填绝对路径，与工具件 Python `str(path)` 行为对表
                // （targets 已按 canonicalize 绝对化，此处即 targets 的 path 本形）
                let finding_path = path.clone();
                // 判断材料轴：manifest 标 json 走 json 规则，否则 text
                let manifest = sih_engine::scrutinator::asset::manifest(pack_name);
                let is_json_pack = manifest.contains("material = \"json\"")
                    || manifest.contains("material=\"json\"");
                if is_json_pack {
                    if let Ok(v) = serde_json::from_str::<serde_json::Value>(text) {
                        findings.extend(run_rules_on_json(pack_name, rules, &v, &finding_path));
                    }
                } else {
                    findings.extend(run_rules_on_text(pack_name, rules, text, &finding_path));
                }
            }
        }
    }

    let report = render_report(&packs_data, &targets, &findings);
    let code = if report.findings.is_empty() { 0 } else { 1 };
    emit(serde_json::to_value(&report).unwrap(), code);
}

fn emit(value: serde_json::Value, code: i32) -> ! {
    println!("{}", serde_json::to_string_pretty(&value).unwrap());
    exit(code)
}

fn read_args() -> Vec<(String, String)> {
    let args: Vec<String> = std::env::args().collect();
    let mut opts: Vec<(String, String)> = Vec::new();
    let mut i = 2;
    while i < args.len() {
        if args[i].starts_with("--") && i + 1 < args.len() {
            opts.push((
                args[i].trim_start_matches('-').to_string(),
                args[i + 1].clone(),
            ));
            i += 2;
        } else {
            i += 1;
        }
    }
    opts
}

fn collect_trails(opts: &[(String, String)]) -> Vec<String> {
    opts.iter()
        .filter(|(k, _)| k == "trail")
        .map(|(_, v)| v.clone())
        .collect()
}

fn first_value<'a>(opts: &'a [(String, String)], key: &str) -> Option<&'a str> {
    for (k, v) in opts {
        if k == key {
            return Some(v.as_str());
        }
    }
    None
}

fn load_trails_or_die(trails: &[String]) -> Vec<sih_engine::event_stream::event::Event> {
    if trails.is_empty() {
        emit(json!({"error": "缺 --trail"}), 2);
    }
    let mut all: Vec<sih_engine::event_stream::event::Event> = Vec::new();
    for t in trails {
        let path = PathBuf::from(t);
        if !path.exists() {
            emit(json!({"error": "trail 不存在", "path": t}), 2);
        }
        match load_events(path.as_path()) {
            Ok(mut evs) => all.append(&mut evs),
            Err(e) => emit(json!({"error": format!("trail 不可读 {e:?}"), "path": t}), 2),
        }
    }
    all
}

fn attach_trail_info(payload: &mut serde_json::Value, trails: &[String]) {
    if let Some(first) = trails.first() {
        payload["trail"] = serde_json::Value::String(first.clone());
    }
    if trails.len() > 1 {
        payload["trails"] = serde_json::Value::Array(
            trails
                .iter()
                .map(|t| serde_json::Value::String(t.clone()))
                .collect(),
        );
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let cmd = args.get(1).map(|s| s.as_str()).unwrap_or("");
    let opts = read_args();
    let trails = collect_trails(&opts);

    match cmd {
        "alarms" => {
            let events = load_trails_or_die(&trails);
            let view = alarms_view(&events);
            let code = view.exit_code_suggested;
            let mut payload = serde_json::to_value(&view).unwrap();
            attach_trail_info(&mut payload, &trails);
            emit(payload, code);
        }
        "heartbeat" => {
            let events = load_trails_or_die(&trails);
            let Some(at) = first_value(&opts, "at") else {
                emit(json!({"error": "缺 --at YYYY-MM-DD"}), 2)
            };
            let date = match NaiveDate::parse_from_str(at, "%Y-%m-%d") {
                Ok(d) => d,
                Err(e) => emit(json!({"error": format!("--at 解析失败 {e}")}), 2),
            };
            let view = heartbeat_view(&events, date);
            let mut payload = serde_json::to_value(&view).unwrap();
            attach_trail_info(&mut payload, &trails);
            emit(payload, 0);
        }
        "settle" => {
            let events = load_trails_or_die(&trails);
            let Some(date_str) = first_value(&opts, "date") else {
                emit(json!({"error": "缺 --date YYYY-MM-DD"}), 2)
            };
            let date = match NaiveDate::parse_from_str(date_str, "%Y-%m-%d") {
                Ok(d) => d,
                Err(e) => emit(json!({"error": format!("--date 解析失败 {e}")}), 2),
            };
            // 在泊复检名单 = heartbeat 配对产出，复用同一参照日
            let hb = heartbeat_view(&events, date);
            let view = settle_view(&events, date, hb.parking);
            let mut payload = serde_json::to_value(&view).unwrap();
            attach_trail_info(&mut payload, &trails);
            emit(payload, 0);
        }
        _ => emit(
            json!({"error": "用法 viewer <alarms|heartbeat|settle> --trail <路径> [--at YYYY-MM-DD | --date YYYY-MM-DD]"}),
            2,
        ),
    }
}

mod tests {
    //! viewfix-solo 跨链装载层单元测试。
    //!
    //! 三组：read_args 允许多次同名旗标共址、collect_trails 按参序保留全部
    //! --trail、attach_trail_info 单链逐字节不变 + 多链 trails 数组在档。
    //! 跨链集成测试以 cargo test 整库形态跑（sih-engine/tests/cli_multitrail.rs），
    //! 走真实 7 链 + tempfile 双链 + 主程序入口。

    use super::*;

    /// read_args 允许多次同名旗标共址，按参序保留全部。
    /// 整改前 HashMap 同 key 覆盖，仅留最后一条。
    #[test]
    fn r1_read_args_preserves_repeated_flags_in_order() {
        let parsed = vec![
            ("trail".to_string(), "a.ndjson".to_string()),
            ("at".to_string(), "2026-08-25".to_string()),
            ("trail".to_string(), "b.ndjson".to_string()),
            ("trail".to_string(), "c.ndjson".to_string()),
        ];
        // 模拟 read_args 的解析路径：仅取 --key val 对，按出现次序
        let collected = collect_trails(&parsed);
        assert_eq!(collected, vec!["a.ndjson", "b.ndjson", "c.ndjson"]);
    }

    /// collect_trails 零参序命中返空数组。
    #[test]
    fn r2_collect_trails_empty_when_absent() {
        let parsed = vec![("at".to_string(), "2026-08-25".to_string())];
        assert!(collect_trails(&parsed).is_empty());
    }

    /// attach_trail_info：单链保持 trail 字符串逐字节不变（回归断言）。
    #[test]
    fn r3_attach_trail_info_single_chain_byte_identical() {
        let mut payload = json!({"consumable_count": 0, "parking": []});
        attach_trail_info(&mut payload, &["only.ndjson".to_string()]);
        let s = serde_json::to_string(&payload).unwrap();
        // 单链不增 trails 字段，仅有 trail 字符串
        assert!(s.contains("\"trail\":\"only.ndjson\""));
        assert!(!s.contains("\"trails\""));
    }

    /// attach_trail_info：多链增 trails 数组按参序排列，trail 字段保持首条。
    #[test]
    fn r4_attach_trail_info_multi_chain_trails_array_in_order() {
        let mut payload = json!({"consumable_count": 0, "parking": []});
        let trails = vec![
            "08-25.ndjson".to_string(),
            "08-26.ndjson".to_string(),
            "08-27.ndjson".to_string(),
        ];
        attach_trail_info(&mut payload, &trails);
        assert_eq!(payload["trail"], "08-25.ndjson");
        assert_eq!(
            payload["trails"],
            json!(["08-25.ndjson", "08-26.ndjson", "08-27.ndjson"])
        );
    }

    /// first_value 取 --key 首条命中（同 key 重复时取首）。
    #[test]
    fn r5_first_value_returns_first_match() {
        let parsed = vec![
            ("at".to_string(), "2026-08-25".to_string()),
            ("at".to_string(), "2026-08-31".to_string()),
        ];
        assert_eq!(first_value(&parsed, "at"), Some("2026-08-25"));
        assert_eq!(first_value(&parsed, "date"), None);
    }
}

