        let locks = temp_dir("g1").join("absent.ndjson");
        let trail = temp_dir("g1").join("trail.ndjson");
        assert!(check_locks(&locks, &trail, None).is_ok());
    }

    // G2 他会话持锁即拒并报持锁方。
