        std::fs::write(&trail, "").unwrap();
        match check_locks(&locks, &trail, Some("sessB")) {
            Err(LockGateError::Held { holders }) => assert_eq!(holders, vec!["sessA".to_string()]),
            other => panic!("应 Held 实得 {other:?}"),
        }
        // 无会话号同样拒。
        assert!(matches!(
            check_locks(&locks, &trail, None),
