fn t7_concurrent_append_race_two_processes() {
        let manifest = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
        let bin = manifest.join("target/debug/scribe");
        if !bin.exists() {
            panic!("scribe 未构建");
        }
