pub fn match_path_glob(pattern: &str, path: &str) -> bool {
    if pattern == "**" || pattern == "**/*" {
        return true;
    }
    // 编译模式为正则：(?:^|/) 前缀 + 模式体
    // 模式体：`**/` → `(?:[^/]+/)*`、`*` → `[^/]*`、`?` → `[^/]`、其他字面量
    let mut body = String::new();
    let mut i = 0;
    let n = pattern.len();
    let bytes = pattern.as_bytes();
    while i < n {
        if i + 3 <= n && &bytes[i..i + 3] == b"**/" {
            body.push_str("(?:[^/]+/)*");
            i += 3;
        } else if bytes[i] == b'*' {
            body.push_str("[^/]*");
            i += 1;
        } else if bytes[i] == b'?' {
            body.push_str("[^/]");
            i += 1;
        } else {
            // ASCII 字面量用 regex::escape，非 ASCII 直接 push
            let c = pattern[i..].chars().next().unwrap();
            let clen = c.len_utf8();
            // escape 只对 ASCII 安全字母元字符；非 ASCII 视为字面
            body.push_str(&regex::escape(&pattern[i..i + clen]));
            i += clen;
        }
    }
    let full = format!("(?:^|/){body}");
    match regex::Regex::new(&full) {
        Ok(re) => re.is_match(path),
        Err(_) => false,
    }
}

pub fn match_fnmatch_glob(text: &str, pattern: &str) -> bool {
    // 逐次编译小而稀疏；包内模式有限，确定性优先
    let re = match build_fnmatch_regex(pattern) {
        Ok(re) => re,
        Err(_) => return false,
    };
    re.is_match(text)
}

fn build_fnmatch_regex(pattern: &str) -> Result<regex::Regex, String> {
    if pattern == "*" {
        return regex::Regex::new("(?s:.*)\\z").map_err(|e| e.to_string());
    }
    let chars: Vec<char> = pattern.chars().collect();
    let n = chars.len();
    let mut res = String::new();
    let mut i = 0usize;
    while i < n {
        let c = chars[i];
        i += 1;
        match c {
            '*' => res.push_str(".*"),
            '?' => res.push('.'),
            '[' => {
                let mut j = i;
                if j < n && chars[j] == '!' {
                    j += 1;
                }
                if j < n && chars[j] == ']' {
                    j += 1;
                }
                while j < n && chars[j] != ']' {
                    j += 1;
                }
                if j >= n {
                    res.push_str("\\[");
                } else {
                    let mut stuff: String = chars[i..j].iter().collect();
                    if stuff.starts_with('!') {
                        stuff = format!("^{}", &stuff[1..]);
                    } else if stuff.starts_with('^') {
                        stuff = format!("\\{stuff}");
                    }
                    res.push('[');
                    res.push_str(&stuff);
                    res.push(']');
                    i = j + 1;
                }
            }
            _ => res.push_str(&regex::escape(&c.to_string())),
        }
    }
    regex::Regex::new(&format!("(?s:{res})\\z")).map_err(|e| e.to_string())
}

pub struct AlarmEntry {
    /// 事件唯一 ID
    pub event_id: String,
    /// 事件类型
    pub event_type: String,
    /// 关联文档 ID
    pub doc_id: String,
    /// ISO 8601 时间戳
    pub timestamp: String,
    /// 事件哈希
    pub event_hash: String,
}

pub struct AlarmsView {
    /// 异常事件集合，按事件时间戳升序
    pub alarms: Vec<AlarmEntry>,
    /// 异常事件总数
    pub total: usize,
    /// 退出码建议：0 = 空，1 = 非空
    pub exit_code_suggested: i32,
}

pub fn consumable_events(events: &[Event]) -> Vec<AlarmEntry> {
    let mut out: Vec<AlarmEntry> = events
        .iter()
        .filter(|e| e.event_class.as_deref() == Some("consumable"))
        .map(|e| AlarmEntry {
            event_id: e.event_id.clone(),
            event_type: e.event_type.clone(),
            doc_id: e.doc_id.clone(),
            timestamp: e.timestamp.to_rfc3339(),
            event_hash: e.event_hash.clone(),
        })
        .collect();
    out.sort_by(|a, b| a.timestamp.cmp(&b.timestamp));
    out
}

pub fn alarms_view(events: &[Event]) -> AlarmsView {
    let alarms = consumable_events(events);
    let total = alarms.len();
    let exit_code_suggested = if total == 0 { 0 } else { 1 };
    AlarmsView { alarms, total, exit_code_suggested }
}

